<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Activity,AlertTriangle,Mail,CheckCircle2,BookOpen,CircleGauge,CreditCard,Globe2,LayoutDashboard,LoaderCircle,LockKeyhole,LogOut,Menu,Pencil,Plus,RefreshCw,Router,Search,Server,ShieldCheck,Users,X} from 'lucide-vue-next'
import {api,ApiError,session,type AuditEvent,type CurrentUser,type LocationRow,type ProxyRow,type Stats} from './api'
import BillingView from './BillingView.vue'
import UsersView from './UsersView.vue'
import BooksView from './BooksView.vue'
// Product name is hidden for now; set VITE_BRAND_NAME=RouteGuard to bring it back.
const brand=import.meta.env.VITE_BRAND_NAME||'Network Console'
document.title=`${brand} Admin`
import countryData from './data/countries.json'
type View='overview'|'proxies'|'locations'|'activity'|'billing'|'users'|'books'|'proxyForm'
const view=ref<View>('overview'),authenticated=ref(!!session.token),loading=ref(false),error=ref(''),mobileNav=ref(false),search=ref('')
const route=useRoute(),router=useRouter()
const stats=ref<Stats|null>(null),proxies=ref<ProxyRow[]>([]),locations=ref<LocationRow[]>([]),activity=ref<AuditEvent[]>([]),user=ref<CurrentUser|null>(null)
const login=reactive({email:'',password:''}),form=reactive({label:'',provider:'managed',countryCode:'',countryName:'',host:'',port:8080,protocol:'http',username:'',password:'',allocationMode:'SHARED',maxAssignments:null as number|null})
const passwordForm=reactive({currentPassword:'',newPassword:'',confirmPassword:'',code:''})
// First sign-in: a security code is e-mailed before the temporary password can be replaced.
const codeState=reactive({sentTo:'',sentAt:0,sending:false,now:Date.now(),failed:false})
setInterval(()=>{codeState.now=Date.now()},1000)
const codeCooldown=computed(()=>Math.max(0,Math.ceil((codeState.sentAt+60000-codeState.now)/1000)))
async function sendPasswordCode(){if(codeState.sending||codeCooldown.value>0)return;codeState.sending=true;error.value='';try{const r=await api.passwordCode();codeState.sentTo=r.email;codeState.sentAt=Date.now();codeState.failed=!r.sent}catch(e){error.value=message(e)}finally{codeState.sending=false}}
const editingId=ref<string|null>(null)
const countries=(countryData as Array<{code:string;name:string;iso:boolean}>).filter(c=>c.iso&&c.code.length===2).sort((a,b)=>a.name.localeCompare(b.name))
const nav=[{id:'overview' as View,path:'/',label:'Overview',icon:LayoutDashboard},{id:'proxies' as View,path:'/proxies',label:'Proxy inventory',icon:Server},{id:'locations' as View,path:'/locations',label:'Locations',icon:Globe2},{id:'users' as View,path:'/users',label:'Users',icon:Users},{id:'billing' as View,path:'/billing',label:'Billing',icon:CreditCard},{id:'books' as View,path:'/books',label:'Books',icon:BookOpen},{id:'activity' as View,path:'/activity',label:'Audit activity',icon:Activity}]
const titles:Record<View,[string,string]>={overview:['Network overview','Live operational state across the network.'],proxies:['Proxy inventory','Manage encrypted upstream endpoints and capacity.'],locations:['Locations','Coverage grouped by exit country.'],activity:['Audit activity','A traceable record of administrative events.'],billing:['Billing','Subscriptions, top-ups, payments and pricing.'],users:['Users','Accounts and the sites they use RouteGuard for.'],books:['Books','Ledgers, balances, income statement and reconciliation.'],proxyForm:['Proxy configuration','Configure an encrypted upstream endpoint.']}
const filtered=computed(()=>{const q=search.value.toLowerCase().trim();return q?proxies.value.filter(p=>[p.label,p.host,p.provider,p.countryName,p.countryCode].some(x=>x?.toLowerCase().includes(q))):proxies.value})
const message=(e:unknown)=>e instanceof ApiError&&e.status===403?'This account does not have administrator access.':e instanceof Error?e.message:'Something went wrong.'
async function load(){loading.value=true;error.value='';try{const me=await api.me();user.value=me;if(me.mustChangePassword){if(!codeState.sentTo)void sendPasswordCode();return}const [s,p,l,a]=await Promise.all([api.dashboard(),api.proxies(),api.locations(),api.audit()]);stats.value=s;proxies.value=p.results;locations.value=l;activity.value=a.results;syncRoute()}catch(e){if(e instanceof ApiError&&e.status===401)logout();error.value=message(e)}finally{loading.value=false}}
async function signIn(){loading.value=true;error.value='';try{await api.login(login.email,login.password);authenticated.value=true;login.password='';if(route.path==='/login')await router.replace('/');await load()}catch(e){session.token=null;error.value=message(e)}finally{loading.value=false}}
function logout(){session.token=null;authenticated.value=false;stats.value=null;user.value=null;void router.replace('/login')}
async function changePassword(){error.value='';if(passwordForm.newPassword!==passwordForm.confirmPassword){error.value='The new passwords do not match.';return}loading.value=true;try{const result=await api.changePassword(passwordForm.currentPassword,passwordForm.newPassword,passwordForm.code.replace(/\D/g,''));user.value=result.user;Object.assign(passwordForm,{currentPassword:'',newPassword:'',confirmPassword:'',code:''});Object.assign(codeState,{sentTo:'',sentAt:0,failed:false});await load()}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(p:ProxyRow){try{await api.proxyAction(p.id,p.status==='DISABLED'?'enable':'disable');await load()}catch(e){error.value=message(e)}}
function resetForm(){Object.assign(form,{label:'',provider:'managed',countryCode:'',countryName:'',host:'',port:8080,protocol:'http',username:'',password:'',allocationMode:'SHARED',maxAssignments:null})}
function openAdd(){void router.push('/proxies/new')}
function fillEdit(p:ProxyRow){editingId.value=p.id;Object.assign(form,{label:p.label,provider:p.provider,countryCode:p.countryCode,countryName:p.countryName,host:p.host,port:p.port,protocol:p.protocol,username:p.username,password:'',allocationMode:p.allocationMode,maxAssignments:p.maxAssignments})}
function openEdit(p:ProxyRow){void router.push(`/proxies/${p.id}/edit`)}
function selectCountry(){const match=countries.find(c=>c.name.toLowerCase()===form.countryName.trim().toLowerCase());form.countryCode=match?match.code.toUpperCase():''}
async function saveProxy(){loading.value=true;error.value='';try{const payload:Record<string,unknown>={...form,countryCode:form.countryCode.toUpperCase()};if(!form.password)delete payload.password;if(editingId.value)await api.updateProxy(editingId.value,payload);else await api.createProxy(payload);editingId.value=null;resetForm();await load();await router.push('/proxies')}catch(e){error.value=message(e)}finally{loading.value=false}}
function cancelProxyForm(){editingId.value=null;resetForm();error.value='';void router.push('/proxies')}
function navigate(path:string){mobileNav.value=false;void router.push(path)}
function syncRoute(){
  if(route.name==='proxy-new'){view.value='proxyForm';editingId.value=null;resetForm();return}
  if(route.name==='proxy-edit'){view.value='proxyForm';const proxy=proxies.value.find(p=>p.id===String(route.params.id));if(proxy)fillEdit(proxy);return}
  view.value=route.name==='proxies'?'proxies':route.name==='locations'?'locations':route.name==='activity'?'activity':route.name==='billing'?'billing':route.name==='users'||route.name==='user-detail'?'users':route.name==='books'?'books':'overview'
}
function ago(v:string){const m=(Date.now()-new Date(v).getTime())/60000;return m<1?'just now':m<60?`${Math.floor(m)}m ago`:m<1440?`${Math.floor(m/60)}h ago`:new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(new Date(v))}
watch(()=>route.fullPath,()=>{if(!authenticated.value&&route.path!='/login')void router.replace('/login');else if(authenticated.value&&route.path==='/login')void router.replace('/');else syncRoute()},{immediate:true})
onMounted(()=>{if(authenticated.value)load()})
</script>

<template>
<main v-if="!authenticated" class="login-shell">
  <section class="login-story"><div class="brand"><span><Router :size="22"/></span>{{brand}}</div><div><p class="eyebrow">ADMIN CONTROL PLANE</p><h1>Keep every route<br><em>accountable.</em></h1><p>Operate your proxy network, monitor assignment health, and audit every change from one secure console.</p></div><aside><i></i><p><strong>Gateway protected</strong><small>Provider credentials remain encrypted at rest.</small></p></aside></section>
  <section class="login-panel"><form @submit.prevent="signIn"><div class="mobile-brand brand"><span><Router :size="20"/></span>{{brand}}</div><p class="eyebrow">SECURE ACCESS</p><h2>Welcome back</h2><p class="muted">Sign in with an administrator account.</p><div v-if="error" class="alert"><AlertTriangle :size="17"/>{{error}}</div><label>Email address<input v-model="login.email" type="email" autocomplete="username" placeholder="admin@example.com" required></label><label>Password<input v-model="login.password" type="password" autocomplete="current-password" placeholder="Enter your password" required></label><button class="primary wide" :disabled="loading"><LoaderCircle v-if="loading" class="spin" :size="18"/><LockKeyhole v-else :size="18"/>Sign in to console</button><p class="security"><ShieldCheck :size="15"/>Access is limited to staff accounts.</p></form></section>
</main>
<div v-else class="app">
  <main v-if="user?.mustChangePassword" class="password-gate"><form @submit.prevent="changePassword"><div class="brand"><span><Router :size="21"/></span>{{brand}}</div><div class="gate-icon"><LockKeyhole :size="25"/></div><p class="eyebrow">FIRST SIGN-IN</p><h1>Secure your admin account</h1><p class="muted">Replace the temporary password before entering the control plane. To confirm it's you, we email a security code to your address.</p><div v-if="error" class="alert"><AlertTriangle :size="17"/>{{error}}</div><div class="code-note" :class="{warn:codeState.failed}"><Mail :size="16"/><p v-if="codeState.sending&&!codeState.sentTo">Sending a code to your email…</p><p v-else-if="codeState.failed">We couldn't send the email just now. Try “Send a new code” in a moment.</p><p v-else-if="codeState.sentTo">We sent a 6-digit code to <b>{{codeState.sentTo}}</b>. It expires in 30 minutes — check Spam or Junk if you can't see it.</p><p v-else>Request a code to continue.</p></div><label>Security code from your email<input v-model="passwordForm.code" class="code-input" inputmode="numeric" autocomplete="one-time-code" maxlength="7" placeholder="••••••" required></label><button type="button" class="code-resend" :disabled="codeState.sending||codeCooldown>0" @click="sendPasswordCode">{{codeCooldown>0?`Send a new code in ${codeCooldown}s`:codeState.sentTo?'Send a new code':'Email me a code'}}</button><label>Temporary password<input v-model="passwordForm.currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input v-model="passwordForm.newPassword" type="password" minlength="8" autocomplete="new-password" required></label><label>Confirm new password<input v-model="passwordForm.confirmPassword" type="password" minlength="8" autocomplete="new-password" required></label><button class="primary wide" :disabled="loading"><LoaderCircle v-if="loading" class="spin" :size="18"/><ShieldCheck v-else :size="18"/>Set new password</button><button type="button" class="gate-logout" @click="logout">Sign out</button></form></main>
  <template v-else>
  <aside :class="['sidebar',{open:mobileNav}]"><div class="brand"><span><Router :size="21"/></span>{{brand}} <small>ADMIN</small></div><button class="close" @click="mobileNav=false"><X/></button><nav><button v-for="n in nav" :key="n.id" :class="{active:view===n.id||(view==='proxyForm'&&n.id==='proxies')}" @click="navigate(n.path)"><component :is="n.icon" :size="18"/>{{n.label}}</button></nav><div class="system"><i></i><strong>System operational</strong><small>{{stats?.proxies.total||0}} endpoints observed</small></div><footer><b>{{(user?.email||'A')[0].toUpperCase()}}</b><p><strong>{{user?.username||'Administrator'}}</strong><small>{{user?.email}}</small></p><button @click="logout"><LogOut :size="17"/></button></footer></aside><div v-if="mobileNav" class="scrim" @click="mobileNav=false"></div>
  <section class="workspace"><header><button class="menu" @click="mobileNav=true"><Menu/></button><div><small>CONTROL PLANE / {{view==='proxyForm'?'PROXIES / CONFIGURE':view.toUpperCase()}}</small><h1>{{view==='proxyForm'?(editingId?'Edit proxy':'Add proxy'):titles[view][0]}}</h1><p>{{titles[view][1]}}</p></div><aside v-if="view!=='proxyForm'&&view!=='billing'&&view!=='users'&&view!=='books'"><button class="icon" @click="load"><RefreshCw :class="{spin:loading}" :size="18"/></button><button class="primary" @click="openAdd"><Plus :size="18"/>Add proxy</button></aside></header><div v-if="error" class="alert page-alert"><AlertTriangle :size="17"/>{{error}}<button @click="error=''">×</button></div>
  <div v-if="view==='overview'" class="page"><section class="routing"><p><i :class="{off:!stats?.routingEnabled}"></i><span><strong>Routing {{stats?.routingEnabled?'enabled':'paused'}}</strong><small>Global gateway policy</small></span></p><small>{{stats?.routingEnabled?'Traffic can be assigned to healthy endpoints.':'New routing is currently disabled.'}}</small></section><section class="metrics"><article><span><Server/></span><p>Total proxies<strong>{{stats?.proxies.total??'—'}}</strong><small>{{stats?.proxies.available||0}} ready</small></p></article><article><span><Router/></span><p>Active assignments<strong>{{stats?.assignments.active??'—'}}</strong><small>{{locations.length}} locations</small></p></article><article><span><CircleGauge/></span><p>Unhealthy<strong>{{stats?.proxies.unhealthy??'—'}}</strong><small>{{stats?.proxies.disabled||0}} disabled</small></p></article><article><span><Users/></span><p>Active users<strong>{{stats?.users.active??'—'}}</strong><small>of {{stats?.users.total||0}} accounts</small></p></article></section><section class="overview"><article class="panel"><div class="panel-head"><p><strong>Network inventory</strong><small>Availability by endpoint state</small></p><button @click="navigate('/proxies')">View inventory</button></div><div class="inventory"><div class="ring" :style="{'--ready':`${stats?.proxies.total?(stats.proxies.available/stats.proxies.total)*100:0}%`}"><p><b>{{stats?.proxies.available||0}}</b><small>ready</small></p></div><ul><li><i class="ready"></i>Available <b>{{stats?.proxies.available||0}}</b></li><li><i class="assigned"></i>Assigned <b>{{stats?.proxies.assigned||0}}</b></li><li><i class="disabled"></i>Disabled <b>{{stats?.proxies.disabled||0}}</b></li><li><i class="reserved"></i>Reserved <b>{{stats?.proxies.reserved||0}}</b></li></ul></div></article><article class="panel"><div class="panel-head"><p><strong>Recent activity</strong><small>Latest security and routing events</small></p><button @click="navigate('/activity')">View all</button></div><div class="events"><div v-for="e in activity.slice(0,5)" :key="e.id"><span><Activity :size="16"/></span><p><strong>{{e.eventType.replaceAll('_',' ').toLowerCase()}}</strong><small>{{e.actor||'System'}} · {{ago(e.createdAt)}}</small></p></div><p v-if="!activity.length" class="empty">No activity yet.</p></div></article></section></div>
  <div v-else-if="view==='proxies'" class="page"><section class="panel table-panel"><div class="tools"><label><Search :size="17"/><input v-model="search" placeholder="Search host, provider or location"></label><small>{{filtered.length}} endpoints</small></div><div class="table-wrap"><table><thead><tr><th>Endpoint</th><th>Location</th><th>Status</th><th>Health</th><th>Assignments</th><th>Credentials</th><th></th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><b>{{p.label||p.host}}</b><small>{{p.protocol}}://{{p.host}}:{{p.port}}</small></td><td><b>{{p.countryCode}}</b><small>{{p.countryName}}</small></td><td><em :class="p.status.toLowerCase()">{{p.status}}</em></td><td><mark :class="p.healthStatus.toLowerCase()"><i></i>{{p.healthStatus}}</mark></td><td>{{p.activeAssignmentCount}}<small>{{p.allocationMode.toLowerCase()}}</small></td><td><span class="credential"><LockKeyhole :size="14"/>{{p.hasPassword?'Encrypted':'None'}}</span></td><td><div class="row-actions"><button class="row-action edit" @click="openEdit(p)"><Pencil :size="12"/>Edit</button><button class="row-action" @click="toggle(p)">{{p.status==='DISABLED'?'Enable':'Disable'}}</button></div></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty">No matching proxies.</td></tr></tbody></table></div></section></div>
  <div v-else-if="view==='locations'" class="page locations"><article v-for="l in locations" :key="l.countryCode"><b>{{l.countryCode}}</b><div><h2>{{l.countryName}}</h2><p>{{l.providers.join(' · ')}}</p></div><dl><div><dt>Endpoints</dt><dd>{{l.proxies}}</dd></div><div><dt>Enabled</dt><dd>{{l.enabled}}</dd></div><div><dt>Assigned</dt><dd>{{l.activeAssignments}}</dd></div><div><dt>Unhealthy</dt><dd>{{l.unhealthy}}</dd></div></dl></article></div>
  <BillingView v-else-if="view==='billing'" @unauthorized="logout"/>
  <UsersView v-else-if="view==='users'" @unauthorized="logout"/>
  <BooksView v-else-if="view==='books'" @unauthorized="logout"/>
  <div v-else-if="view==='activity'" class="page"><section class="panel timeline"><div class="panel-head"><p><strong>Audit log</strong><small>Immutable operational activity</small></p></div><article v-for="e in activity" :key="e.id"><span><CheckCircle2 :size="17"/></span><p><strong>{{e.eventType.replaceAll('_',' ')}}</strong><small>{{e.actor||'System'}} · {{e.resourceType||'system'}}</small></p><time>{{ago(e.createdAt)}}</time></article></section></div>
  <div v-else class="page proxy-editor"><form class="panel" @submit.prevent="saveProxy"><section class="editor-intro"><div><p class="eyebrow">UPSTREAM ENDPOINT</p><h2>{{editingId?'Update proxy configuration':'Add a proxy to inventory'}}</h2><p>{{editingId?'Changes apply to future gateway connections. Leave the password blank to preserve the current encrypted credential.':'The upstream password is encrypted by the backend before it is stored.'}}</p></div><span><ShieldCheck :size="23"/></span></section><div class="form-grid"><label class="full">Display label<input v-model="form.label" placeholder="Kenya datacenter 01"></label><label class="full">Provider<input v-model="form.provider" required></label><label class="full country-field">Country name<input v-model="form.countryName" list="routeguard-countries" placeholder="Start typing a country name…" autocomplete="off" required @input="selectCountry" @change="selectCountry"><datalist id="routeguard-countries"><option v-for="country in countries" :key="country.code" :value="country.name">{{country.code.toUpperCase()}}</option></datalist><small v-if="form.countryCode">Country code: {{form.countryCode}}</small><small v-else>Select a country from the list.</small></label><label class="full">Host<input v-model="form.host" placeholder="proxy.example.com" required></label><label>Port<input v-model.number="form.port" type="number" min="1" max="65535" required></label><label>Protocol<select v-model="form.protocol"><option>http</option><option>https</option><option>socks5</option></select></label><label class="full">Username template<input v-model="form.username" placeholder="customer-{country}-{session}"></label><label class="full">{{editingId?'New password (optional)':'Password'}}<input v-model="form.password" type="password" autocomplete="new-password" :placeholder="editingId?'Leave blank to keep current password':'Stored encrypted'"></label><label>Allocation<select v-model="form.allocationMode"><option value="SHARED">Shared</option><option value="EXCLUSIVE">Exclusive</option></select></label><label>Max assignments<input v-model.number="form.maxAssignments" type="number" min="1" placeholder="Unlimited"></label></div><footer class="editor-actions"><button type="button" class="cancel-button" @click="cancelProxyForm">Cancel</button><button class="primary" :disabled="loading||!form.countryCode"><LoaderCircle v-if="loading" class="spin" :size="17"/><Pencil v-else-if="editingId" :size="17"/><Plus v-else :size="17"/>{{editingId?'Save changes':'Add endpoint'}}</button></footer></form></div>
  </section>
  </template>
</div>
</template>
